package com.pranit.productsupport.bff.api;
import com.fasterxml.jackson.databind.JsonNode;import com.pranit.productsupport.bff.client.CoreApiClient;import com.pranit.productsupport.contracts.*;import jakarta.validation.Valid;import java.util.Map;import org.springframework.http.HttpMethod;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class BffController {private final CoreApiClient core;public BffController(CoreApiClient c){core=c;}
 @PostMapping("/auth/register") public ResponseEntity<JsonNode> register(@Valid @RequestBody RegisterRequest r){return core.forward(HttpMethod.POST,"/internal/v1/auth/register",r,null,Map.of());}
 @PostMapping("/auth/login") public ResponseEntity<JsonNode> login(@Valid @RequestBody LoginRequest r){return core.forward(HttpMethod.POST,"/internal/v1/auth/login",r,null,Map.of());}
 @GetMapping("/products") public ResponseEntity<JsonNode> products(@RequestHeader(value="Authorization",required=false) String auth){return core.forward(HttpMethod.GET,"/internal/v1/products",null,auth,Map.of());}
 @PostMapping("/admin/products") public ResponseEntity<JsonNode> createProduct(@RequestHeader("Authorization") String auth,@Valid @RequestBody CreateProductRequest r){return core.forward(HttpMethod.POST,"/internal/v1/admin/products",r,auth,Map.of());}
 @PostMapping("/admin/orders") public ResponseEntity<JsonNode> createOrder(@RequestHeader("Authorization") String auth,@Valid @RequestBody CreateOrderRequest r){return core.forward(HttpMethod.POST,"/internal/v1/admin/orders",r,auth,Map.of());}
 @GetMapping("/orders/me") public ResponseEntity<JsonNode> orders(@RequestHeader("Authorization") String auth){return core.forward(HttpMethod.GET,"/internal/v1/orders/me",null,auth,Map.of());}
 @PostMapping("/tickets") public ResponseEntity<JsonNode> createTicket(@RequestHeader("Authorization") String auth,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody CreateTicketRequest r){return core.forward(HttpMethod.POST,"/internal/v1/tickets",r,auth,Map.of("Idempotency-Key",key));}
 @GetMapping("/tickets/me") public ResponseEntity<JsonNode> tickets(@RequestHeader("Authorization") String auth,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return core.forward(HttpMethod.GET,"/internal/v1/tickets/me?page="+page+"&size="+size,null,auth,Map.of());}
 @GetMapping("/support/tickets") public ResponseEntity<JsonNode> supportQueue(@RequestHeader("Authorization") String auth,@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){String query="?page="+page+"&size="+size+(status==null?"":"&status="+status);return core.forward(HttpMethod.GET,"/internal/v1/support/tickets"+query,null,auth,Map.of());}
 @PatchMapping("/tickets/{id}/assignment") public ResponseEntity<JsonNode> assign(@RequestHeader("Authorization") String auth,@PathVariable long id,@Valid @RequestBody AssignTicketRequest r){return core.forward(HttpMethod.PATCH,"/internal/v1/tickets/"+id+"/assignment",r,auth,Map.of());}
 @GetMapping("/tickets/{id}") public ResponseEntity<JsonNode> ticket(@RequestHeader("Authorization") String auth,@PathVariable long id){return core.forward(HttpMethod.GET,"/internal/v1/tickets/"+id,null,auth,Map.of());}
 @PostMapping("/tickets/{id}/comments") public ResponseEntity<JsonNode> comment(@RequestHeader("Authorization") String auth,@PathVariable long id,@Valid @RequestBody CreateCommentRequest r){return core.forward(HttpMethod.POST,"/internal/v1/tickets/"+id+"/comments",r,auth,Map.of());}
 @GetMapping("/tickets/{id}/comments") public ResponseEntity<JsonNode> comments(@RequestHeader("Authorization") String auth,@PathVariable long id){return core.forward(HttpMethod.GET,"/internal/v1/tickets/"+id+"/comments",null,auth,Map.of());}
 @PatchMapping("/tickets/{id}/status") public ResponseEntity<JsonNode> status(@RequestHeader("Authorization") String auth,@PathVariable long id,@Valid @RequestBody UpdateTicketStatusRequest r){return core.forward(HttpMethod.PATCH,"/internal/v1/tickets/"+id+"/status",r,auth,Map.of());}
 @PostMapping("/tickets/{id}/quotes") public ResponseEntity<JsonNode> quote(@RequestHeader("Authorization") String auth,@PathVariable long id,@Valid @RequestBody CreateQuoteRequest r){return core.forward(HttpMethod.POST,"/internal/v1/tickets/"+id+"/quotes",r,auth,Map.of());}
 @GetMapping("/quotes/{id}") public ResponseEntity<JsonNode> getQuote(@RequestHeader("Authorization") String auth,@PathVariable long id){return core.forward(HttpMethod.GET,"/internal/v1/quotes/"+id,null,auth,Map.of());}
 @PostMapping("/quotes/{id}/payment") public ResponseEntity<JsonNode> payment(@RequestHeader("Authorization") String auth,@PathVariable long id){return core.forward(HttpMethod.POST,"/internal/v1/quotes/"+id+"/payment",Map.of(),auth,Map.of());}
 @PostMapping(value="/webhooks/razorpay",consumes="application/json") public ResponseEntity<JsonNode> webhook(@RequestBody byte[] body,@RequestHeader(value="X-Razorpay-Signature",required=false) String signature){return core.forwardRaw("/internal/v1/webhooks/razorpay",body,signature);}
 @PostMapping("/dev/payments/{id}/capture") public ResponseEntity<JsonNode> mockPaymentCapture(@RequestHeader("Authorization") String auth,@PathVariable long id){return core.forward(HttpMethod.POST,"/internal/v1/dev/payments/"+id+"/capture",Map.of(),auth,Map.of());}
}
